if.script:
ec.entity.find("zenith.erp.pos.PosTransaction").condition("sessionId", existingOpen[0].sessionId).condition("statusId", "PtCreated").list().each { st ->
    ec.entity.find("zenith.erp.pos.PosTransactionItem").condition("transactionId", st.transactionId).deleteAll()
    ec.entity.find("zenith.erp.pos.PosPayment").condition("transactionId", st.transactionId).deleteAll()
    ec.entity.find("zenith.erp.pos.PosItemPriceOverride").condition("transactionId", st.transactionId).deleteAll()
    try { st.delete() } catch (Exception e) { st.statusId = 'PtVoided'; st.update() }
}

actions.script:
def _opId = ec.user.userAccount?.partyId
if (_opId) {
    ec.entity.find("zenith.erp.pos.PosSession")
        .condition("operatorPartyId", _opId).condition("organizationPartyId", _posAccess.organizationPartyId).condition("statusId", "PsOpen").list().each { os ->
        def soldCount = ec.entity.find("zenith.erp.pos.PosTransaction")
            .condition("sessionId", os.sessionId).condition("statusId", "PtCompleted").count()
        def retirement = ec.service.sync().name("zenith.pos.PosServices.check#PosSessionRetirement").parameter("sessionId",os.sessionId).call()
        if (soldCount == 0 && !retirement.hasUnfinishedMoney && !retirement.hasHeldSales) {
            ec.entity.find("zenith.erp.pos.PosTransaction").condition("sessionId", os.sessionId).condition("statusId", "PtCreated").list().each { st ->
                ec.entity.find("zenith.erp.pos.PosTransactionItem").condition("transactionId", st.transactionId).deleteAll()
                ec.entity.find("zenith.erp.pos.PosPayment").condition("transactionId", st.transactionId).deleteAll()
                ec.entity.find("zenith.erp.pos.PosItemPriceOverride").condition("transactionId", st.transactionId).deleteAll()
                try { st.delete() } catch (Exception e) { st.statusId = 'PtVoided'; st.update() }
            }
            ec.service.sync().name("update#zenith.erp.pos.PosSession")
                .parameters([sessionId: os.sessionId, statusId:'PsClosed', closeDate: ec.user.nowTimestamp, closingCash: (os.openingCash ?: 0)]).call()
            ec.logger.info("Start-fresh: retired abandoned POS session " + os.sessionId + " (operator " + _opId + ")")
        }
    }
}

ec.entity.find("zenith.erp.pos.PosTransaction").condition("sessionId", sessionId).condition("statusId", "PtCreated").list().each { st ->
    ec.entity.find("zenith.erp.pos.PosTransactionItem").condition("transactionId", st.transactionId).deleteAll()
    ec.entity.find("zenith.erp.pos.PosPayment").condition("transactionId", st.transactionId).deleteAll()
    ec.entity.find("zenith.erp.pos.PosItemPriceOverride").condition("transactionId", st.transactionId).deleteAll()
    try { st.delete() } catch (Exception e) { st.statusId = 'PtVoided'; st.update() }
}

def fyStr = null
if (txn.organizationPartyId) {
    try {
        def fyResult = ec.service.sync().name("zenith.base.LocalizationServices.get#FinancialYearDates")
            .parameter("organizationPartyId", txn.organizationPartyId).call()
        fyStr = fyResult?.fyLabel
    } catch (Exception e) { /* fall through to date-based number */ }
}
if (!fyStr) {
    def now = ec.user.nowTimestamp
    fyStr = new java.text.SimpleDateFormat("yyyy-MM").format(now)
}
// Atomic per-(org, financial-year) bill counter: an O(1) row-locked increment instead of a
// growing full-table count scan, and race-safe (two registers can never mint the same number).
def org = txn?.organizationPartyId ?: '_NA_'
def seqKey = org + "_" + fyStr
def nextNum
def counter = ec.entity.find("zenith.erp.pos.PosBillSequence").condition("seqKey", seqKey).forUpdate(true).one()
if (counter != null) {
    nextNum = ((counter.lastNumber ?: 0) as int) + 1
    ec.service.sync().name("update#zenith.erp.pos.PosBillSequence").parameters([seqKey:seqKey, lastNumber:nextNum]).call()
} else {
    // First bill for this org+FY: seed from the existing max so we never collide with or renumber prior bills.
    int mx = 0
    def prior = ec.entity.find("zenith.erp.pos.PosTransaction").condition("organizationPartyId", org)
        .condition("transactionNumber", "like", "POS/${fyStr}/%").selectField("transactionNumber").list()
    for (r in prior) {
        def m = (r.transactionNumber =~ /\/(\d+)$/)
        if (m.find()) { int n = m.group(1) as int; if (n > mx) mx = n }
    }
    nextNum = mx + 1
    try {
        ec.service.sync().name("create#zenith.erp.pos.PosBillSequence").parameters([seqKey:seqKey, lastNumber:nextNum]).call()
    } catch (Exception e) {
        // concurrent first-bill for this key: another thread seeded it — re-read locked and increment
        def c2 = ec.entity.find("zenith.erp.pos.PosBillSequence").condition("seqKey", seqKey).forUpdate(true).one()
        nextNum = (((c2?.lastNumber ?: mx) as int)) + 1
        ec.service.sync().name("update#zenith.erp.pos.PosBillSequence").parameters([seqKey:seqKey, lastNumber:nextNum]).call()
    }
}
def seqNum = String.format("%05d", nextNum)
transactionNumber = "POS/${fyStr}/${seqNum}"

if (paymentMethod != 'Cash') {
    def existing = ec.entity.find('zenith.erp.pos.PosPayment').condition('transactionId',transactionId).list()
    def nonCash = existing.findAll { it.paymentMethod != 'Cash' }.sum { (it.amount ?: 0) as BigDecimal } ?: BigDecimal.ZERO
    if (nonCash + amount > ((_ptxn.payableAmount ?: 0) as BigDecimal)) ec.message.addError('Non-cash payments cannot exceed the bill total.')
}

if (_openCredit && paymentMethod=='Cash') {
    def drawers=ec.entity.find('zenith.erp.pos.PosSession').condition('organizationPartyId',_posAccess.organizationPartyId).condition('operatorPartyId',ec.user.userAccount?.partyId).condition('statusId','PsOpen').list()
    if (!collectionSessionId && drawers.size()==1) collectionSessionId=drawers[0].sessionId
    if (!drawers.any { it.sessionId==collectionSessionId }) ec.message.addError('Open/select your POS drawer before collecting cash for this credit bill.')
} else if (!_openCredit) {
    def saleSession=ec.entity.find('zenith.erp.pos.PosSession').condition('sessionId',_ptxn.sessionId).one()
    if (saleSession?.statusId!='PsOpen') ec.message.addError('The sale session must be open before payment.')
    collectionSessionId=_ptxn.sessionId
} else { collectionSessionId=null }

if.script:
def customer = ec.entity.find('mantle.party.PartyDetailAndRole').condition('partyId', customerPartyId).limit(1).list()
def detail = customer ? customer[0] : null
def canonicalName = detail?.organizationName ?: (((detail?.firstName ?: '') + ' ' + (detail?.lastName ?: '')).trim())
def phoneMechs = ec.entity.find('mantle.party.contact.PartyContactMech').condition('partyId', customerPartyId)
    .conditionDate('fromDate', 'thruDate', ec.user.nowTimestamp).list()
def matchesPhone = phoneMechs.any { pcm ->
    def number = ec.entity.find('mantle.party.contact.TelecomNumber').condition('contactMechId', pcm.contactMechId).one()
    def digits = ((number?.countryCode ?: '') + (number?.areaCode ?: '') + (number?.contactNumber ?: '')).replaceAll('[^0-9]', '')
    digits && (digits == custDigits || (digits.length() > 10 && custDigits.length() == 10 && digits.endsWith(custDigits)))
}
if (!canonicalName || !(matchesPhone || customerPartyId == ('POSCUST_' + txn.organizationPartyId + '_' + custDigits)))
    ec.message.addError('Select a saved customer with a matching phone, or add a new customer.')
else customerName = canonicalName

actions.script:
import groovy.json.JsonOutput
def itemsList = items.collect { [productId: it.productId, productName: it.productName,
    quantity: it.quantity, unitPrice: it.unitPrice, discountPercent: it.discountPercent,
    lineTotal: it.lineTotal, sourceTransactionId:transactionId, salesModeId:it.salesModeId,
    manualPrice:it.manualPrice, taxOn:((it.totalTaxAmount ?: 0) > 0 ? 'Y' : 'N')] }
itemsJson = JsonOutput.toJson(itemsList)

def snapshot = new groovy.json.JsonSlurper().parseText(held.itemsJson ?: '[]')
def sourceId = snapshot ? snapshot[0].sourceTransactionId : null
def source = sourceId ? ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',sourceId).forUpdate(true).one() : null
def targetSession = ec.entity.find('zenith.erp.pos.PosSession').condition('sessionId',sessionId).one()
if (!targetSession || targetSession.statusId != 'PsOpen') {
    ec.message.addError('Session is not open'); return
}
if (source && source.statusId == 'PtHeld' && source.organizationPartyId == targetSession.organizationPartyId) {
    // Resume the original cart: preserve tax-off, manual prices, mode locks, customer and audit rows.
    if (curOpen && curOpen[0].transactionId != sourceId && !curItems) {
        curOpen[0].statusId = 'PtVoided'; curOpen[0].update()
    }
    source.sessionId = sessionId; source.statusId = 'PtCreated'; source.update()
    transactionId = sourceId
    held.recallTime = ec.user.nowTimestamp; held.statusId = 'PhRecalled'; held.update()
}

syncedIds=[]; failedCount=0
transactions.each { raw ->
    try {
        def r=ec.service.sync().name('zenith.pos.PosServices.import#OfflinePosSale').parameters([terminalId:terminalId,saleJson:raw as String]).call()
        if (!ec.message.hasError() && r?.offlineId) syncedIds.add(r.offlineId)
        else failedCount++
    } catch (Exception e) { failedCount++ }
    ec.message.clearErrors()
}
syncedCount=syncedIds.size()

def sale=new groovy.json.JsonSlurper().parseText(saleJson)
def org=_posAccess.organizationPartyId
if (!(sale instanceof Map) || !sale.offlineId || sale.offlineId.toString().size()>120 || sale.terminalId!=terminalId || (sale.organizationPartyId && sale.organizationPartyId!=org) || !(sale.items instanceof List) || !sale.items || !['Cash','Card','UPI'].contains(sale.paymentMethod)) {
    ec.message.addError('Invalid offline sale or terminal.'); return
}
// Lock serializes replay on a terminal; the org/id key also isolates identical ids in different tenants.
ec.entity.find('zenith.erp.pos.PosTerminal').condition('terminalId',terminalId).forUpdate(true).one()
def key=java.util.UUID.nameUUIDFromBytes((org+'\u0000'+sale.offlineId).getBytes('UTF-8')).toString()
def prior=ec.entity.find('zenith.erp.pos.PosOfflineTransaction').condition('offlineTransactionId',key).one()
if (prior?.statusId=='OtSynced') { offlineId=sale.offlineId; return }
// Compatibility with older imports, always through the caller's owned transaction.
def legacy=ec.entity.find('zenith.erp.pos.PosPayment').condition('referenceNumber','OFFLINE:'+sale.offlineId).list()
if (legacy.any { ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',it.transactionId).condition('organizationPartyId',org).condition('statusId','PtCompleted').one() }) { offlineId=sale.offlineId; return }
def sess=sale.sessionId ? ec.entity.find('zenith.erp.pos.PosSession').condition('sessionId',sale.sessionId).condition('terminalId',terminalId).condition('organizationPartyId',org).condition('statusId','PsOpen').one() : null
if (!sess) { ec.message.addError('Open the original terminal session before syncing this sale.'); return }
def cr=ec.service.sync().name('zenith.pos.PosServices.create#PosTransaction').parameters([sessionId:sess.sessionId,reuseOpenCart:false]).call()
sale.items.each { it ->
    if (!(it instanceof Map) || it.qty==null || it.price==null) { ec.message.addError('Invalid offline item.'); return }
    ec.service.sync().name('zenith.pos.PosServices.add#PosTransactionItem').parameters([transactionId:cr.transactionId,productId:it.productId,quantity:it.qty,unitPrice:it.price,taxOn:sale.taxOn ?: 'Y']).call()
}
if (ec.message.hasError()) return
def txn=ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',cr.transactionId).one()
// Never invent cash collected. Old tax-free snapshots that differ remain on the device for review.
if (sale.total==null || (sale.total as BigDecimal).compareTo(txn.payableAmount as BigDecimal)!=0) { ec.message.addError('Offline total differs from the recorded payable; review the retained sale.'); return }
ec.service.sync().name('zenith.pos.PosServices.process#PosPayment').parameters([transactionId:cr.transactionId,paymentMethod:sale.paymentMethod,amount:sale.total,referenceNumber:'OFFLINE:'+sale.offlineId,bypassModeRules:true]).call()
ec.service.sync().name('zenith.pos.PosServices.complete#PosTransaction').parameters([transactionId:cr.transactionId]).call()
if (ec.message.hasError()) return
ec.service.sync().name('create#zenith.erp.pos.PosOfflineTransaction').parameters([offlineTransactionId:key,terminalId:terminalId,offlineTimestamp:ec.user.nowTimestamp,syncedTimestamp:ec.user.nowTimestamp,transactionDataJson:saleJson,itemCount:sale.items.size(),grandTotal:sale.total,paymentMethod:sale.paymentMethod,statusId:'OtSynced',syncAttempts:1,createdTransactionId:cr.transactionId]).call()
if (!ec.message.hasError()) offlineId=sale.offlineId

ec.user.loginAnonymousIfNoUser()
def cutoff = new java.sql.Timestamp(ec.user.nowTimestamp.time - (olderThanHours ?: 24) * 3600000L)
voidedCount = 0
ec.entity.find("zenith.erp.pos.PosTransaction").condition("statusId", "PtCreated").list().each { st ->
    if (st.transactionNumber) return                 // numbered = issued; never touch (belt+suspenders — PtCreated should never have one)
    if (!st.sessionId) return                        // unknown provenance — leave alone
    def sess = ec.entity.find("zenith.erp.pos.PosSession").condition("sessionId", st.sessionId).one()
    if (!sess || sess.statusId != 'PsClosed') return // open/live session — a cashier may be mid-sale; NEVER touch
    if (sess.closeDate == null || sess.closeDate.after(cutoff)) return  // grace period after close
    def payCount = ec.entity.find("zenith.erp.pos.PosPayment").condition("transactionId", st.transactionId).count()
    if (payCount > 0 || ((st.paidAmount ?: 0) as BigDecimal) > 0) {
        ec.logger.warn("void#OrphanedPosCarts: SKIPPING PtCreated cart " + st.transactionId + " on closed session " + st.sessionId + " — it has recorded payments; needs manual review")
        return
    }
    st.statusId = 'PtVoided'
    st.update()
    voidedCount++
}
if (voidedCount) ec.logger.info("void#OrphanedPosCarts: voided " + voidedCount + " orphaned PtCreated cart(s) on sessions closed > " + (olderThanHours ?: 24) + "h")

if (!sessionId) {
    def sessions = ec.entity.find('zenith.erp.pos.PosSession').condition('organizationPartyId',_cashAccess.organizationPartyId)
        .condition('operatorPartyId',ec.user.userAccount?.partyId).condition('statusId','PsOpen').list()
    if (sessions.size() == 1) sessionId = sessions[0].sessionId
    else if (sessions.size() > 1) ec.message.addError('Choose the POS session for this cash entry.')
}
if (sessionId) {
    def session = ec.entity.find('zenith.erp.pos.PosSession').condition('sessionId',sessionId).one()
    if (session?.statusId != 'PsOpen') ec.message.addError('Cash entries can only be recorded against an open POS session.')
}

def txns = ec.entity.find("zenith.erp.pos.PosTransaction")
    .condition("sessionId", sessionId)
    .condition("statusId", "PtCompleted").list()
def txnIds = txns*.transactionId

// New payments name the collecting drawer. Legacy rows retain original-session attribution,
// but a closed drawer never acquires a later collection retroactively.
def received=ec.entity.find('zenith.erp.pos.PosPayment').condition('collectionSessionId',sessionId).condition('paymentMethod','Cash').list()
if (txnIds) received.addAll(ec.entity.find('zenith.erp.pos.PosPayment').condition('transactionId','in',txnIds).condition('collectionSessionId',null).condition('paymentMethod','Cash').list())
received=received.findAll { pay ->
    def bill=ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',pay.transactionId).condition('organizationPartyId',session.organizationPartyId).one()
    bill?.statusId=='PtCompleted' && (!session.closeDate || !pay.paymentDate || pay.paymentDate<=session.closeDate)
}
cashReceived=received.sum { (it.amount ?: 0) as BigDecimal } ?: BigDecimal.ZERO
changeGiven=BigDecimal.ZERO
def receivedIds=received*.paymentId
received*.transactionId.unique().each { id ->
    def allCash=ec.entity.find('zenith.erp.pos.PosPayment').condition('transactionId',id).condition('paymentMethod','Cash').orderBy('paymentDate').orderBy('paymentId').list()
    // Change belongs to the latest cash collection, never a card-only amended bill.
    if (allCash && receivedIds.contains(allCash[-1].paymentId)) {
        def bill=ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',id).one()
        changeGiven+=(bill.changeAmount ?: 0) as BigDecimal
    }
}

def movements = ec.entity.find("zenith.erp.pos.PosCashManagement").condition("sessionId",sessionId).list()
movementNet = BigDecimal.ZERO
movements.each { movement ->
    def amount = (movement.amount ?: 0) as BigDecimal
    if (movement.transactionTypeEnumId == 'PcmFloatIn') movementNet += amount
    else if (['PcmFloatOut','PcmBankDrop','PcmPettyCash'].contains(movement.transactionTypeEnumId)) movementNet -= amount
}
def entries = ec.entity.find("zenith.erp.pos.PosCashEntry").condition("sessionId",sessionId).condition("organizationPartyId",session.organizationPartyId).list()
entries.each { entry ->
    def amount = (entry.amount ?: 0) as BigDecimal
    if (entry.entryType == 'CashIn') movementNet += amount
    else if (entry.entryType == 'CashOut') movementNet -= amount
}
expectedCash = ((session.openingCash ?: 0) as BigDecimal) + cashReceived - changeGiven + movementNet

def txn = ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',transactionId).forUpdate(true).one()
if (txn.statusId != 'PtCreated') { ec.message.addError('Only an open cart can change its tax destination.'); return }
def lines = ec.entity.find('zenith.erp.pos.PosTransactionItem').condition('transactionId',transactionId).list()
for (line in lines) {
    def product = ec.entity.find('mantle.product.Product').condition('productId',line.productId).one()
    def mode = line.salesModeId ? ec.entity.find('zenith.erp.pos.PosSalesMode').condition('salesModeId',line.salesModeId).one() : null
    def enabled = taxOn ? taxOn != 'N' : ((line.totalTaxAmount ?: 0) > 0)
    def result = ec.service.sync().name('zenith.tax.TaxServices.calculate#Tax').parameters([
        organizationPartyId:txn.organizationPartyId, originRegionGeoId:txn.originRegionGeoId,
        destinationRegionGeoId:txn.destinationRegionGeoId, transactionType:'SALE',
        items:[[productId:line.productId, productTaxCode:line.productTaxCode, taxCategoryId:product?.taxCategoryId,
            quantity:line.quantity, unitAmount:line.unitPrice, discountAmount:line.discountAmount,
            isTaxInclusive:mode?.isTaxInclusive ?: 'N']]]).call()
    if (ec.message.hasError()) return
    def taxed = result?.taxedItems ? result.taxedItems[0] : null
    def base = (line.quantity as BigDecimal) * (line.unitPrice as BigDecimal) - ((line.discountAmount ?: 0) as BigDecimal)
    line.taxableAmount = enabled && taxed?.taxableAmount != null ? taxed.taxableAmount : base
    line.totalTaxAmount = enabled ? (taxed?.totalTaxAmount ?: 0) : 0
    line.lineTotal = line.taxableAmount + line.totalTaxAmount; line.update()
    ec.entity.find('zenith.erp.tax.TaxLineDetail').condition('referenceType','PosTransactionItem')
        .condition('referenceId',transactionId).condition('referenceSeqId',line.itemSeqId).deleteAll()
    if (enabled && taxed?.taxBreakdowns) ec.service.sync().name('zenith.tax.TaxServices.store#TaxLineDetails')
        .parameters([referenceType:'PosTransactionItem',referenceId:transactionId,referenceSeqId:line.itemSeqId,taxBreakdowns:taxed.taxBreakdowns]).call()
}
ec.service.sync().name('zenith.pos.PosServices.recalculate#TransactionTotals').parameter('transactionId',transactionId).call()

def carts = ec.entity.find('zenith.erp.pos.PosTransaction').condition('sessionId',sessionId)
    .condition('statusId','in',['PtCreated','PtHeld']).orderBy('transactionId').forUpdate(true).list()
hasUnfinishedMoney = carts.any { cart -> cart.transactionNumber || ((cart.paidAmount ?: 0) > 0) ||
    ec.entity.find('zenith.erp.pos.PosPayment').condition('transactionId',cart.transactionId).count() > 0 }
hasHeldSales = ec.entity.find('zenith.erp.pos.PosHeldTransaction').condition('sessionId',sessionId).condition('statusId','PhHeld').count() > 0

def bills=ec.entity.find('zenith.erp.pos.PosTransaction').condition('organizationPartyId',_reportAccess.organizationPartyId)
    .condition('statusId','PtCompleted').condition('entryDate','greater-equals',fromDate).condition('entryDate','less-equals',thruDate).list()
def byId=bills.collectEntries { [(it.transactionId):it] }
def payments=bills ? ec.entity.find('zenith.erp.pos.PosPayment').condition('transactionId','in',byId.keySet().toList())
    .orderBy('paymentDate').orderBy('paymentId').list() : []
def latestCash=[:]
payments.each { if(it.paymentMethod?.equalsIgnoreCase('Cash')) latestCash[it.transactionId]=it.paymentId }
def methods=[:]
payments.each { pay ->
    def key=(pay.paymentMethod ?: 'Other').toString().trim()
    if(key.equalsIgnoreCase('Cash'))key='Cash'
    if(key.equalsIgnoreCase('Card'))key='Card'
    if(key.equalsIgnoreCase('UPI'))key='UPI'
    // Preserve the report's existing legacy-method aliases.
    if(['netbanking','net banking','net_banking'].contains(key.toLowerCase()))key='Net Banking'
    if(key.equalsIgnoreCase('Wallet'))key='Wallet'
    if(key.equalsIgnoreCase('Credit'))key='Credit'
    if(!methods[key])methods[key]=[paymentMethod:key,totalAmount:BigDecimal.ZERO,ids:new HashSet()]
    def net=(pay.amount ?: 0) as BigDecimal
    if(latestCash[pay.transactionId]==pay.paymentId)net-=((byId[pay.transactionId].changeAmount ?: 0) as BigDecimal)
    methods[key].totalAmount+=net
    methods[key].ids.add(pay.transactionId)
}
totalAmount=methods.values().inject(BigDecimal.ZERO){sum,m -> sum+m.totalAmount}
rows=methods.values().collect { m -> [paymentMethod:m.paymentMethod,totalAmount:m.totalAmount,transactionCount:m.ids.size(),
    percentage:totalAmount>0 ? (m.totalAmount*100/totalAmount).setScale(2,java.math.RoundingMode.HALF_UP) : BigDecimal.ZERO] }.sort { -it.totalAmount }
